// Bring DVector into scope for the diagonal helper used in tests
#[allow(unused_imports)]
use nalgebra::DVector as DVec;

//! Short-Time Fourier Transform and analytic signal computation.

use num_complex::Complex;
use rustfft::FftPlanner;

/// Computes the analytic signal of a real-valued input using the Hilbert transform.
///
/// The analytic signal `z(t) = x(t) + j·H{x(t)}` has a one-sided spectrum; its magnitude is the
/// instantaneous envelope and its argument is the instantaneous phase.
///
/// # Algorithm
/// 1. Forward FFT of the real input.
/// 2. Apply the one-sided spectral window H: `H[0] = 1`, `H[1..N/2] = 2`, `H[N/2] = 1` (for
///    even N), `H[N/2+1..] = 0`.
/// 3. Inverse FFT → analytic signal.
///
/// # Examples
/// ```
/// use musicrs::analytic_signal;
/// use std::f64::consts::PI;
/// let n = 256;
/// let cos: Vec<f64> = (0..n).map(|i| (2.0 * PI * 10.0 * i as f64 / n as f64).cos()).collect();
/// let z = analytic_signal(&cos);
/// // Magnitude should be approximately 1 everywhere (after transients settle)
/// for &c in &z[10..n-10] {
///     assert!((c.norm() - 1.0).abs() < 0.01);
/// }
/// ```
pub fn analytic_signal(data: &[f64]) -> Vec<Complex<f64>> {
    let n = data.len();
    let mut planner = FftPlanner::<f64>::new();

    // Forward FFT
    let fft_forward = planner.plan_fft_forward(n);
    let mut spectrum: Vec<Complex<f64>> = data.iter().map(|&x| Complex::new(x, 0.0)).collect();
    fft_forward.process(&mut spectrum);

    // One-sided spectral window
    let half = n / 2;
    spectrum[0] *= 1.0; // DC – unchanged
    for k in 1..half {
        spectrum[k] *= 2.0;
    }
    // Nyquist bin (index half) is kept unchanged when N is even
    // Negative-frequency bins are zeroed
    for k in (half + 1)..n {
        spectrum[k] = Complex::new(0.0, 0.0);
    }

    // Inverse FFT
    let fft_inverse = planner.plan_fft_inverse(n);
    fft_inverse.process(&mut spectrum);

    // Normalise
    let norm = n as f64;
    spectrum.iter().map(|c| c / norm).collect()
}

/// Computes the Short-Time Fourier Transform of a real-valued signal.
///
/// Returns a matrix of shape `[freq_bins][num_windows]` where
/// `freq_bins = nfft / 2 + 1` (single-sided spectrum via real FFT).
///
/// # Arguments
/// * `data`       – Real-valued input samples.
/// * `nfft`       – Window (FFT) size. Must be ≥ 1.
/// * `no_overlap` – Number of samples shared between consecutive windows.
///
/// # Examples
/// ```
/// use musicrs::stft;
/// use std::f64::consts::PI;
/// let n = 512;
/// let freq_bin = 16usize;
/// let sr = 512.0_f64;
/// let sine: Vec<f64> = (0..n)
///     .map(|i| (2.0 * PI * freq_bin as f64 * i as f64 / sr).sin())
///     .collect();
/// let result = stft(&sine, 64, 0);
/// // Each window should have a peak at `freq_bin` (relative to the window size)
/// assert!(!result.is_empty());
/// ```
pub fn stft(data: &[f64], nfft: usize, no_overlap: usize) -> Vec<Vec<Complex<f64>>> {
    assert!(nfft >= 1, "nfft must be at least 1");
    assert!(no_overlap < nfft, "no_overlap must be less than nfft");

    let step = nfft - no_overlap;
    let freq_bins = nfft / 2 + 1;
    let mut planner = FftPlanner::<f64>::new();
    // Use real-to-complex FFT plan (standard forward FFT on real-padded input)
    let fft = planner.plan_fft_forward(nfft);

    let num_windows = if data.len() >= nfft {
        (data.len() - nfft) / step + 1
    } else {
        0
    };

    // result[freq_bin][window_index]
    let mut result: Vec<Vec<Complex<f64>>> = vec![vec![Complex::new(0.0, 0.0); num_windows]; freq_bins];

    for (win_idx, start) in (0..).zip((0..).step_by(step).take(num_windows)) {
        let end = start + nfft;
        let mut buf: Vec<Complex<f64>> = data[start..end]
            .iter()
            .map(|&x| Complex::new(x, 0.0))
            .collect();
        fft.process(&mut buf);
        for bin in 0..freq_bins {
            result[bin][win_idx] = buf[bin];
        }
    }

    result
}

#[cfg(test)]
mod tests {
    use super::*;
    use approx::assert_abs_diff_eq;
    use std::f64::consts::PI;

    /// Pure cosine → analytic signal magnitude ≈ 1 (away from edges).
    #[test]
    fn analytic_signal_cosine_magnitude() {
        let n = 256usize;
        let f0 = 10.0_f64;
        let data: Vec<f64> = (0..n)
            .map(|i| (2.0 * PI * f0 * i as f64 / n as f64).cos())
            .collect();
        let z = analytic_signal(&data);
        // Skip 10 samples at each edge where Gibbs artefacts may occur
        for c in &z[10..n - 10] {
            assert_abs_diff_eq!(c.norm(), 1.0, epsilon = 0.02);
        }
    }

    /// Analytic signal of a cosine has imaginary part ≈ -sine (shifted by -π/2).
    #[test]
    fn analytic_signal_imag_is_negative_sine() {
        let n = 256usize;
        let f0 = 8.0_f64;
        let data: Vec<f64> = (0..n)
            .map(|i| (2.0 * PI * f0 * i as f64 / n as f64).cos())
            .collect();
        let z = analytic_signal(&data);
        for i in 10..n - 10 {
            // H{cos(ωt)} = +sin(ωt), so z(t) = cos(ωt) + i·sin(ωt)
            let expected_imag = (2.0 * PI * f0 * i as f64 / n as f64).sin();
            assert_abs_diff_eq!(z[i].im, expected_imag, epsilon = 0.02);
        }
    }

    /// STFT column count matches expected number of windows.
    #[test]
    fn stft_window_count() {
        let data = vec![0.0f64; 100];
        let nfft = 16;
        let overlap = 8;
        let step = nfft - overlap; // 8
        let expected_windows = (data.len() - nfft) / step + 1; // (100 - 16) / 8 + 1 = 11
        let result = stft(&data, nfft, overlap);
        assert_eq!(result[0].len(), expected_windows);
    }

    /// STFT freq_bins = nfft/2 + 1.
    #[test]
    fn stft_freq_bins() {
        let data = vec![0.0f64; 64];
        let nfft = 32;
        let result = stft(&data, nfft, 0);
        assert_eq!(result.len(), nfft / 2 + 1);
    }

    /// STFT of a pure sine wave has a peak at the expected frequency bin.
    #[test]
    fn stft_peak_at_correct_bin() {
        let nfft = 64usize;
        let target_bin = 4usize; // frequency = target_bin * (sr / nfft)
        // Generate enough samples for several non-overlapping windows
        let n = nfft * 8;
        let data: Vec<f64> = (0..n)
            .map(|i| (2.0 * PI * target_bin as f64 * i as f64 / nfft as f64).sin())
            .collect();
        let result = stft(&data, nfft, 0);
        // In each window, bin `target_bin` should dominate
        for win in 0..result[0].len() {
            let peak_bin = (0..result.len())
                .max_by(|&a, &b| result[a][win].norm().partial_cmp(&result[b][win].norm()).unwrap())
                .unwrap();
            assert_eq!(peak_bin, target_bin);
        }
    }
}

// Integration tests for musicrs
//
// Tests DOA estimation against the pre-recorded single-source WAV test data.
// Each WAV file is a 4-channel, 24-bit PCM, 16 kHz recording whose filename
// encodes the source frequency, true DOA, and duration.

use std::fs;
use std::path::PathBuf;

use nalgebra::DMatrix;
use musicrs::{MusicEstimator, analytic_signal};

// ─────────────────────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────────────────────

/// Parse metadata from a test-data filename.
/// Format: `single-source_<freq>Hz_<doa>deg_<duration>s.wav`
/// Returns `(frequency_hz, doa_degrees, duration_s)`.
fn parse_test_file_meta_params(path: &PathBuf) -> Option<Vec<&str>> {
    path.file_name()
        .and_then(|name| name.to_str())
        .map(|file_name| {
            file_name
                .strip_suffix(".wav")
                .unwrap()
                .split('_')
                .collect::<Vec<&str>>()
        })
}

/// Read a 4-channel, 24-bit PCM WAV file with `hound` and return
/// `(sample_rate, data)` where `data` is a `(4 × n_samples)` real matrix
/// normalised to `[-1, 1]`.
fn read_wav_4ch(path: &PathBuf) -> (u32, DMatrix<f64>) {
    let mut reader = hound::WavReader::open(path).expect("Failed to open WAV file");
    let spec = reader.spec();
    assert_eq!(spec.channels, 4, "Expected 4-channel WAV");
    assert_eq!(spec.bits_per_sample, 24, "Expected 24-bit PCM");

    // hound reads 24-bit samples as i32 (zero-padded in the low bits)
    let raw_samples: Vec<i32> = reader
        .samples::<i32>()
        .map(|s| s.expect("Sample read error"))
        .collect();

    let n_channels = spec.channels as usize;
    let n_samples = raw_samples.len() / n_channels;
    let scale = 2.0_f64.powi(23); // 24-bit signed → [-1, 1]

    // De-interleave: WAV stores [ch0, ch1, ch2, ch3, ch0, ch1, ...]
    let mut data = DMatrix::<f64>::zeros(n_channels, n_samples);
    for (idx, &sample) in raw_samples.iter().enumerate() {
        let ch = idx % n_channels;
        let t = idx / n_channels;
        data[(ch, t)] = sample as f64 / scale;
    }

    (spec.sample_rate, data)
}

// ─────────────────────────────────────────────────────────────────────────────
// Integration test
// ─────────────────────────────────────────────────────────────────────────────

/// For every WAV file in `tests/data/single-source/`, estimate the DOA of the
/// single source and verify it is within ±5° of the ground-truth angle encoded
/// in the filename.
#[test]
fn test_single_source_doa() {
    let estimator = MusicEstimator::default();

    // Tolerance: ±5 degrees
    let tolerance_deg = 5.0_f64;

    let paths = fs::read_dir("./tests/data/single-source")
        .expect("Test data directory not found")
        .filter(|p| {
            let p = p.as_ref().unwrap().path();
            p.extension().and_then(|ext| ext.to_str()) == Some("wav")
        });

    let mut total = 0usize;
    let mut failures: Vec<String> = Vec::new();

    for entry in paths {
        let path = entry.unwrap().path();
        let parts = parse_test_file_meta_params(&path).unwrap();

        let freq_hz: f64 = parts[1]
            .strip_suffix("Hz")
            .unwrap()
            .parse::<f64>()
            .unwrap();
        let true_doa_deg: f64 = parts[2]
            .strip_suffix("deg")
            .unwrap()
            .parse::<f64>()
            .unwrap();
        let _duration_s: f64 = parts[3]
            .strip_suffix("s")
            .unwrap()
            .parse::<f64>()
            .unwrap();

        // ── Read WAV and build complex signal matrix ──────────────────────────
        let (sample_rate, real_data) = read_wav_4ch(&path);
        let n_mics = real_data.nrows();
        let n_samples = real_data.ncols();

        // Convert each microphone channel to its analytic (complex) signal
        let mut complex_data =
            nalgebra::DMatrix::<num_complex::Complex<f64>>::zeros(n_mics, n_samples);
        for m in 0..n_mics {
            let row: Vec<f64> = real_data.row(m).iter().copied().collect();
            let analytic = analytic_signal(&row);
            for (t, c) in analytic.into_iter().enumerate() {
                complex_data[(m, t)] = c;
            }
        }

        // ── Estimate DOA ──────────────────────────────────────────────────────
        let estimated_angles = estimator.estimate_doa(&complex_data, 1, freq_hz);

        let estimated_deg = if estimated_angles.is_empty() {
            failures.push(format!(
                "{:?}: no peak found (expected {:.1}°)",
                path.file_name().unwrap(),
                true_doa_deg
            ));
            total += 1;
            continue;
        } else {
            estimated_angles[0].to_degrees()
        };

        // ── Check accuracy ────────────────────────────────────────────────────
        // A linear x-axis array has mirror symmetry: a(θ) = a(360°−θ).
        // At exactly Nyquist (f == sr/2), the real steering vector adds two more
        // equivalent angles: a(θ) = a(180°−θ) = a(180°+θ).
        let nyquist = sample_rate as f64 / 2.0;
        let is_nyquist = (freq_hz - nyquist).abs() < 0.5;
        let angular_dist = |a: f64, b: f64| -> f64 {
            let d = (a - b).abs();
            if d > 180.0 { 360.0 - d } else { d }
        };
        let equivalent_angles: &[f64] = if is_nyquist {
            &[
                true_doa_deg,
                360.0 - true_doa_deg,
                180.0 - true_doa_deg,
                180.0 + true_doa_deg,
            ]
        } else {
            &[true_doa_deg, 360.0 - true_doa_deg]
        };
        let diff_wrapped = equivalent_angles
            .iter()
            .map(|&t| angular_dist(estimated_deg, t))
            .fold(f64::INFINITY, f64::min);

        if diff_wrapped > tolerance_deg {
            failures.push(format!(
                "{}: expected {:.1}° (equivalents: {:?}), got {:.1}° (error {:.1}°)",
                path.file_name().unwrap().to_str().unwrap(),
                true_doa_deg,
                equivalent_angles,
                estimated_deg,
                diff_wrapped
            ));
        }
        total += 1;
    }

    if !failures.is_empty() {
        panic!(
            "{}/{} files failed DOA accuracy test (tolerance ±{:.0}°):\n{}",
            failures.len(),
            total,
            tolerance_deg,
            failures.join("\n")
        );
    }

    println!("All {total} single-source DOA tests passed (tolerance ±{tolerance_deg:.0}°).");
}

